for(const f of [form,$('profile')]){const select=f.elements.timezone;for(const z of zones){const o=document.createElement('option');o.value=z;o.textContent=z;select.append(o)}addZone(select,browserZone);f.elements.birth_date.addEventListener('input',e=>{const input=e.target;if(e.inputType?.startsWith('delete')){refreshClocks();return}const digits=input.value.replace(/\D/g,'').slice(0,8);const formatted=[digits.slice(0,2),digits.slice(2,4),digits.slice(4)].filter(Boolean).join('.');const caret=input.selectionStart;const oldLength=input.value.length;if(formatted!==input.value){input.value=formatted;const next=Math.min(formatted.length,caret+formatted.length-oldLength);input.setSelectionRange(next,next)};refreshClocks();});setupGeo(f);select.addEventListener('change',refreshClocks);}
