function renderAdvanced(a,period,individual=false){
 const section=el('section',undefined,'stats-ai');section.append(el('h3','Расширенная статистика'));
 if(!a?.reported_accounts){section.append(el('p','Нет расширенных отчётов.','muted'));return section}
 section.append(el('p','Последние отчёты, получено от специалистов: '+a.reported_accounts+' · '+date(a.reported_at),'muted'));
 const grid=el('div',undefined,'stats-grid');
 for(const [k,v] of Object.entries(a.counts||{})){const card=el('div',undefined,'stats-kpi');card.append(el('small',analyticsLabels[k]||k),el('strong',String(v)));grid.append(card);}
 section.append(grid,el('h3','Зарегистрированные оплаты'));
 const money=el('p',Object.entries(a.income||{}).map(([k,n])=>new Intl.NumberFormat(accountLocale,{maximumFractionDigits:2}).format(n/100)+' '+k).join(' · ')||'—');section.append(money,el('p','Суммы из последних отчётов за всё время, отдельно по валютам. Не банковские данные.','muted'));
 section.append(el('h3','Действия по модулям · '+period+' дн.'));
 const vals=Object.entries(a.events||{}).sort((x,y)=>y[1]-x[1]),max=Math.max(1,...vals.map(x=>x[1]));
 if(!vals.length)section.append(el('p','Нет зарегистрированных действий за период.','muted'));
 for(const [k,n] of vals){const line=el('div',undefined,'stats-ai-row'),bar=el('div',undefined,'stats-track'),fill=el('span');fill.style.width=(100*n/max)+'%';bar.append(fill);line.append(el('span',analyticsLabels[k]||k),bar,el('strong',String(n)));section.append(line);}
 section.append(el('h3','Устройства · последние отчёты'));
 for(const [k,v] of Object.entries(a.devices||{})){section.append(el('p',({browser:'Браузер',os:'Операционная система',type:'Тип устройства'}[k]||k)+': '+Object.entries(v).map(([label,n])=>label+' — '+n).join(' · ')));}
 return section;
}
let statisticsRequest=0;
async function loadStatistics(){
 const seq=++statisticsRequest,body=$('statisticsBody'),days=$('statisticsPeriod').value;
 body.replaceChildren(el('p','Загрузка…','muted'));
 try{
  const s=await api('admin/statistics?days='+encodeURIComponent(days));if(seq!==statisticsRequest)return;
  const grid=el('div',undefined,'stats-grid');
  for(const [label,n] of [['Всего специалистов',s.total],['Доступ разрешён',s.enabled],['Новые регистрации за период',s.new],['Активные специалисты за период',s.active],['Активность за последние 5 минут',s.recent],['Входов за период',s.logins],['Клиентских карточек (последние отчёты)',s.clients_snapshot],['AI-запросов за период',s.ai_total]]){
   const card=el('div',undefined,'stats-kpi');card.append(el('small',label),el('strong',String(n)));grid.append(card);
  }
  const note=el('p','Отчёты о количестве карточек получены от '+s.reported_accounts+' специалистов. Это не количество уникальных клиентов и не данные за выбранный период.','muted');
  const areas=el('div',undefined,'stats-ai');areas.append(el('h3','Использование AI'));
  const names={chat:'AI-чат',session:'AI-сессии',hypothesis:'AI-гипотезы',diagnosis:'AI-диагностика'};
  for(const [key,n] of Object.entries(s.ai_areas)){const line=el('div',undefined,'stats-ai-row'),bar=el('div',undefined,'stats-track'),fill=el('span');fill.style.width=(s.ai_total?100*n/s.ai_total:0)+'%';bar.append(fill);line.append(el('span',names[key]||key),bar,el('strong',String(n)));areas.append(line);}
  const trend=el('div',undefined,'stats-trend');trend.append(el('h3','Активность по дням'));
  const max=Math.max(1,...s.series.map(x=>x.active));
  for(const row of s.series){const line=el('div',undefined,'stats-ai-row'),bar=el('div',undefined,'stats-track'),fill=el('span');fill.style.width=(100*row.active/max)+'%';bar.append(fill);line.append(el('span',row.day),bar,el('strong',String(row.active)+' / AI '+row.ai));trend.append(line);}
  body.replaceChildren(grid,note,areas,trend,renderAdvanced(s.advanced,s.days));
 }catch(e){if(seq===statisticsRequest)body.replaceChildren(el('p',e.message,'muted'));throw e}
}
