function forgotMode(value){
 forgot=value;register=false;msg('');
 $('loginPasswordRow').hidden=value;form.elements.password.disabled=value;form.elements.password.required=!value;
 $('repeatRow').hidden=true;form.elements.password_repeat.disabled=true;form.elements.password_repeat.required=false;
 $('inviteRow').hidden=true;form.elements.invite.disabled=true;form.elements.invite.required=false;
 $('forgotPassword').hidden=value;
 $('submit').textContent=value?'Отправить ссылку':'Войти';$('mode').textContent=value?'Вернуться ко входу':'Регистрация';
 $('auth').querySelector('h1').textContent=value?'Восстановление пароля':'Вход в аккаунт';
 reset();
}
$('forgotPassword').onclick=()=>{if(!authBusy){forgotMode(true);form.elements.email.focus()}};
$('mode').onclick=()=>{
 if(authBusy)return;if(forgot){forgotMode(false);return;}register=!register;msg('');$('forgotPassword').hidden=register;
 $('repeatRow').hidden=!register;form.elements.password_repeat.disabled=!register;form.elements.password_repeat.required=register;
 $('inviteRow').hidden=!register;form.elements.invite.required=register;form.elements.invite.disabled=!register;
 $('submit').textContent=register?'Проверить лицензию и продолжить':'Войти';
 $('mode').textContent=register?'Войти':'Регистрация';
 $('auth').querySelector('h1').textContent=register?'Регистрация · шаг 1 из 2':'Вход в аккаунт';
 form.elements.password.autocomplete=register?'new-password':'current-password';
 $('captchaHint').textContent='Пройдите проверку безопасности.';reset();
};
form.onsubmit=async e=>{
 e.preventDefault();if(authBusy)return;
 const data=Object.fromEntries(new FormData(form));data.email=String(data.email||'').trim().toLowerCase();data.captcha=captchaToken;
 if(forgot){
  if(!captchaToken){msg('Пройдите проверку безопасности.');return;}
  authBusy=true;updateAuthButton();$('mode').disabled=true;
  msg('Проверяем аккаунт и отправляем письмо…','pending');
  try{const result=await api('password-reset-request',{email:data.email,captcha:captchaToken});if(result.sent!==true)throw Error('Не удалось отправить письмо. Повторите попытку позже.');msg('Аккаунт найден. Ссылка для восстановления отправлена на почту.','success');}
  catch(e){msg(e.message)}finally{authBusy=false;$('mode').disabled=false;reset()}return;
 }
 if(register){data.invite=String(data.invite||'').trim();if(data.password!==data.password_repeat){msg('Пароли не совпадают');form.elements.password_repeat.focus();return;}if(!data.invite){msg('Введите код лицензии.');form.elements.invite.focus();return;}}
 if(!captchaToken){msg('Пройдите проверку безопасности.');return;}
 authBusy=true;updateAuthButton();$('mode').disabled=true;msg(register?'Проверяем лицензию и создаём аккаунт…':'Выполняется вход…');
 try{
  let u;
  try{u=await api(register?'register':'login',data);}
  catch(error){
   // If the account was created but the response was interrupted, resume using its authenticated session.
   try{u=await api('me');if(!u||u.email!==data.email)throw error;}catch{throw error;}
  }
  form.reset();msg('');enterAccount(u);
 }catch(e){msg(e instanceof TypeError?'Не удалось связаться с сервером. Если аккаунт уже создан, попробуйте войти.':e.message);$('authStatus').scrollIntoView({block:'nearest'});reset();}
 finally{authBusy=false;$('mode').disabled=false;updateAuthButton();}
};
