const inviteForm=$('invite'),inviteFilters=$('inviteFilters');
const inviteStates={active:'Действует',used:'Активирован',expired:'Истёк',revoked:'Отозван'};
function setInviteMode(){const trial=inviteForm.elements.access_plan.value==='trial';if(trial)inviteForm.elements.mode.value='email';inviteForm.elements.mode.disabled=trial;const required=inviteForm.elements.mode.value==='email';$('inviteEmailRow').hidden=!required;inviteForm.elements.email.required=required;inviteForm.elements.email.disabled=!required}
inviteForm.elements.mode.onchange=setInviteMode;inviteForm.elements.access_plan.onchange=setInviteMode;setInviteMode();
function showInviteCode(r){$('newInviteResult').hidden=false;$('inviteCode').textContent=r.invite;$('inviteCode').dataset.code=r.invite;$('copyInvite').hidden=false}
function inviteQuery(){const q=new URLSearchParams(new FormData(inviteFilters));q.set('offset',String(inviteOffset));return q.toString()}

let renewalBusy=false,renewalRow=null,renewalInside=false;
const renewalDialog=$('licenseRenewDialog'),renewalForm=$('licenseRenewForm');
function openLicenseRenewal(row,inside){
 if(renewalDialog.open||renewalBusy)return;
 renewalRow=row;renewalInside=inside;
 $('licenseRenewNumber').textContent=row.license_number||'—';
 const select=renewalForm.elements.hours;
 select.replaceChildren(...Array.from(inviteForm.elements.hours.options,o=>o.cloneNode(true)));
 select.value='24';
 $('licenseRenewError').hidden=true;$('licenseRenewError').textContent='';
 renewalDialog.showModal();select.focus();
}
$('licenseRenewCancel').onclick=()=>{if(!renewalBusy)renewalDialog.close()};
renewalDialog.addEventListener('cancel',e=>{if(renewalBusy)e.preventDefault()});
renewalForm.onsubmit=async e=>{
 e.preventDefault();if(renewalBusy||!renewalRow)return;
 const row=renewalRow,inside=renewalInside,hours=Number(renewalForm.elements.hours.value);
 if(![24,72,168,0].includes(hours))return;
 renewalBusy=true;for(const b of renewalForm.querySelectorAll('button,select'))b.disabled=true;
 $('licenseRenewError').hidden=true;
 try{
  const result=await api('admin/invite-reissue',{id:row.id,hours});
  if(result.id!==row.id||result.license_number!==row.license_number||result.status!=='active')throw Error('Не удалось подтвердить перевыпуск лицензии.');
  renewalDialog.close();
  if(result.code)showInviteCode({invite:result.code});
  inviteFilters.elements.status.value='';inviteOffset=0;
  if(inside)await openInvite(result,result.license_number);
  await loadInvites();msg('Лицензия перевыпущена. Номер и код сохранены.');
 }catch(e){
  if(renewalDialog.open){$('licenseRenewError').textContent=e.message;$('licenseRenewError').hidden=false;}else msg(e.message);
 }finally{renewalBusy=false;for(const b of renewalForm.querySelectorAll('button,select'))b.disabled=false;}
};
function addInviteActions(group,row,after=()=>{},inside=false){
 function action(label,cls,endpoint,message,extra={},success='Готово'){
  const b=el('button',label,cls);b.type='button';group.append(b);
  b.onclick=async()=>{if(!await confirmAction(message,label,label))return;for(const btn of group.querySelectorAll('button'))btn.disabled=true;
   try{const result=await api(endpoint,{id:row.id,...extra});after();if(result.invite){showInviteCode(result);inviteOffset=0;}await loadInvites();msg(success)}
   catch(e){msg(e.message)}finally{for(const btn of group.querySelectorAll('button'))btn.disabled=false}
  };
 }
 if(row.status==='active'){
  action('Отозвать','secondary','admin/invite-revoke','Код перестанет действовать. Запись лицензии будет сохранена.',{},'Приглашение отозвано.');
 }
 if(['active','expired','revoked'].includes(row.status)){
  const renew=el('button','Перевыпустить','secondary');renew.type='button';renew.onclick=()=>openLicenseRenewal(row,inside);group.append(renew);
 }
 if(inside&&['revoked','expired'].includes(row.status))action('Удалить','danger','admin/invite-delete','Удалить неактивированную лицензию из реестра? Номер останется зарезервированным.',{},'Приглашение удалено.');
}
let inviteRequest=0;
async function loadInvites(){const seq=++inviteRequest;$('inviteList').replaceChildren(el('p','Загрузка приглашений…','muted'));let result;try{result=await api('admin/invites?'+inviteQuery());}catch(e){if(seq===inviteRequest)$('inviteList').replaceChildren(el('p',e.message,'muted'));throw e;}if(seq!==inviteRequest)return;if(!result.items.length&&inviteOffset>0){inviteOffset=Math.max(0,inviteOffset-50);return loadInvites()}$('inviteCount').textContent='Найдено: '+result.total+' · Страница '+(Math.floor(inviteOffset/50)+1);$('prevInvites').disabled=inviteOffset===0;$('nextInvites').disabled=inviteOffset+50>=result.total;
 const wrap=el('div',undefined,'tablewrap'),table=el('table'),thead=el('thead'),head=el('tr'),body=el('tbody');
 for(const t of ['№','Лицензия / для кого','Создано','Активация до','Статус','Активировал','Действия'])head.append(el('th',t));thead.append(head);table.append(thead);
 for(const [index,row] of result.items.entries()){const number=row.license_number||'—',tr=el('tr'),code=el('td'),open=el('button',row.preview,'invite-open');open.type='button';open.onclick=()=>openInvite(row,number);code.append(open,el('small',row.access_plan==='trial'?'Пробный · 72 часа':'Бессрочный'),el('small',row.comment||row.email||'Не указано'));tr.append(el('td',String(number)),code,el('td',date(row.created)),el('td',row.expires?date(row.expires):'Бессрочно'));
 const status=el('td');status.append(statusBadge(row.status));tr.append(status);
 const used=el('td');used.textContent=shortPerson(row.used_by);tr.append(used);
 const actions=el('td'),group=el('div',undefined,'invite-actions'),detail=el('button','Открыть','secondary');detail.type='button';detail.onclick=()=>openInvite(row,number);group.append(detail);addInviteActions(group,row);actions.append(group);tr.append(actions);body.append(tr)}
 if(!result.items.length){const tr=el('tr'),td=el('td','Приглашений пока нет','empty');td.colSpan=7;tr.append(td);body.append(tr)}table.append(body);wrap.append(table);$('inviteList').replaceChildren(wrap);
}
$('refreshInvites').onclick=()=>go(loadInvites);
inviteFilters.onsubmit=e=>{e.preventDefault();inviteOffset=0;go(loadInvites)};
inviteFilters.elements.status.addEventListener('change',()=>{inviteOffset=0;go(loadInvites)});
$('prevInvites').onclick=()=>{inviteOffset=Math.max(0,inviteOffset-50);go(loadInvites)};
$('nextInvites').onclick=()=>{inviteOffset+=50;go(loadInvites)};
inviteForm.onsubmit=async e=>{e.preventDefault();const submit=inviteForm.querySelector('button');submit.disabled=true;try{const fields=inviteForm.elements;const result=await api('admin/invite',{email:fields.mode.value==='email'?fields.email.value.trim().toLowerCase():'',hours:Number(fields.hours.value),comment:fields.comment.value.trim(),access_plan:fields.access_plan.value});showInviteCode(result);msg('Приглашение создано. Скопируйте код.');inviteOffset=0;inviteFilters.reset();await loadInvites()}catch(e){msg(e.message)}finally{submit.disabled=false}};

